const ICONS={myday:'☼',important:'☆',planned:'▣',assigned:'♙',flagged:'⚑',tasks:'⌂',list:'☰'};
const builtIns=[['myday','我的一天'],['important','重要'],['planned','计划内'],['assigned','已分配给我'],['flagged','已标记的电子邮件'],['tasks','任务']];
const themes=[['blue','#536fa5'],['violet','#8b63ad'],['rose','#c95678'],['coral','#d75e5c'],['green','#3e987a'],['cyan','#3c9392'],['slate','#82909a'],['sky','#6fa7da'],['lilac','#b69aca'],['blush','#e59aac'],['sand','#dfa481'],['mint','#73b99f'],['aqua','#58aaa5'],['fog','#a4b1bb'],['night','linear-gradient(145deg,#13243f,#566f8c 55%,#d7a774)'],['forest','linear-gradient(145deg,#123a32,#29845d 55%,#88b65d)'],['sunset','linear-gradient(145deg,#483b69,#cc6d73 55%,#f1bd7a)']];
const sampleTasks=[
  ['整理本周项目计划','tasks',true,0],['回顾会议记录并提取行动项','tasks',false,1],['每天至少专注工作一小时','tasks',false,1],['预约年度体检','tasks',false,0],['给家人打电话','tasks',true,0],['整理书桌和文件','daily',false,0],['完成产品原型','work',true,0],['购买咖啡豆','tasks',false,0]
].map((x,i)=>({id:'t'+i,title:x[0],list:x[1],important:x[2],myDay:!!x[3],completed:false,due:i===0?todayISO():null,reminder:null,repeat:null,note:'',steps:[],created:Date.now()-i*3600000}));
const initial={view:'myday',lists:[{id:'daily',name:'每日例行'},{id:'work',name:'工作计划'},{id:'reading',name:'阅读清单'}],tasks:sampleTasks,selected:null,search:'',completedOpen:true,sidebarOpen:false,suggestions:false,moreOpen:false,theme:'night',sortMode:'created'};
let state=load();
function todayISO(){const d=new Date();return d.toISOString().slice(0,10)}
function load(){try{const saved={...structuredClone(initial),...JSON.parse(localStorage.getItem('todo-state')||'{}')};if(!saved.demo20Seeded){const names=['制定今天的三项重点','回复项目更新消息','整理下载文件夹','完成产品需求草稿','阅读行业报告二十分钟','预约下周会议时间','更新个人学习计划','备份重要工作文件','清理收件箱未读邮件','购买本周生活用品','完成英语听力练习','记录今日工作复盘','检查本月预算进度','整理桌面与工作区域','准备明天的会议材料','联系朋友确认周末安排','更新待阅读书目','散步三十分钟','规划下一阶段目标','睡前整理明日待办'];const current=saved.tasks.filter(t=>t.myDay&&!t.completed).length;names.slice(0,Math.max(0,20-current)).forEach((title,i)=>saved.tasks.push({id:'demo-'+i+'-'+Date.now(),title,list:'tasks',important:i%7===0,myDay:true,completed:false,due:i%6===0?todayISO():null,reminder:null,repeat:null,note:'',steps:[],created:Date.now()-100000-i}));saved.demo20Seeded=true}return saved}catch{return structuredClone(initial)}}
function save(){localStorage.setItem('todo-state',JSON.stringify({...state,selected:null,suggestions:false,sidebarOpen:false}))}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function activeTasks(){return state.tasks.filter(t=>!t.completed)}
function countFor(id){return activeTasks().filter(t=>matchesView(t,id)).length}
function matchesView(t,v=state.view){if(v==='myday')return t.myDay;if(v==='important')return t.important;if(v==='planned')return !!t.due;if(v==='assigned'||v==='flagged')return false;if(v==='tasks')return t.list==='tasks';return t.list===v}
function viewInfo(){const bi=builtIns.find(x=>x[0]===state.view);if(bi)return{id:bi[0],name:bi[1],icon:ICONS[bi[0]]};const l=state.lists.find(x=>x.id===state.view);return{id:l?.id||'tasks',name:l?.name||'任务',icon:ICONS.list}}
function filtered(){const q=state.search.trim().toLowerCase();let tasks=state.tasks.filter(t=>q?t.title.toLowerCase().includes(q):matchesView(t));return tasks.sort((a,b)=>state.sortMode==='alpha'?a.title.localeCompare(b.title,'zh-CN'):state.sortMode==='important'?Number(b.important)-Number(a.important):b.created-a.created)}
function render(){renderSidebar();renderMain();renderDetail();renderSuggestions();save()}
function renderSidebar(){const s=document.querySelector('#sidebar');s.className='sidebar'+(state.sidebarOpen?' mobile-open':'');s.innerHTML=`<div class="profile"><div class="avatar">你</div><div class="profile-copy"><div class="profile-name">我的账户</div><div class="profile-mail">专注今天重要的事</div></div></div><div class="search-wrap"><input id="search" value="${esc(state.search)}" placeholder="搜索" aria-label="搜索任务"><span class="search-icon">⌕</span></div><div class="nav-scroll">${builtIns.map(([id,name],i)=>`${i===6?'<div class="nav-divider"></div>':''}<button class="nav-item ${state.view===id?'active':''}" data-view="${id}" style="--nav-color:${id==='important'?'#f0a5b7':id==='planned'?'#78d1c9':'#7eafff'}"><span class="nav-icon">${ICONS[id]}</span><span class="nav-label">${name}</span>${countFor(id)?`<span class="count">${countFor(id)}</span>`:''}</button>`).join('')}<div class="nav-divider"></div>${state.lists.map(l=>`<button class="nav-item ${state.view===l.id?'active':''}" data-view="${l.id}"><span class="nav-icon">${ICONS.list}</span><span class="nav-label">${esc(l.name)}</span>${countFor(l.id)?`<span class="count">${countFor(l.id)}</span>`:''}</button>`).join('')}</div><div class="new-list"><button class="add-list" data-action="new-list">＋　新建列表</button><button class="group-btn" title="新建组">▣</button></div>`;
  s.querySelector('#search').addEventListener('input',e=>{state.search=e.target.value;renderMain()})
}
function renderMain(){const m=document.querySelector('#main'),info=viewInfo(),tasks=filtered(),active=tasks.filter(t=>!t.completed),done=tasks.filter(t=>t.completed),dark=!['myday','daily'].includes(state.view);m.className='main'+(dark?' dark':'');const accents={important:'#f3a8bd',planned:'#81d8d0',tasks:'#7f9eff'};m.style.setProperty('--page-accent',accents[state.view]||'#fff');const theme=themes.find(x=>x[0]===state.theme)?.[1];m.style.background=!dark&&theme?theme:'';
  const cards=active.map(card).join('')+(done.length?`<button class="section-title" data-action="toggle-completed">⌄　已完成　${done.length}</button>${state.completedOpen?done.map(card).join(''):''}`:'');
  m.innerHTML=`<div class="main-content"><div class="page-head"><div><h1 class="heading"><span class="heading-icon">${info.icon}</span>${esc(info.name)}</h1>${state.view==='myday'?`<p class="page-subtitle">${new Intl.DateTimeFormat('zh-CN',{weekday:'long',month:'long',day:'numeric'}).format(new Date())}</p>`:''}</div><div class="head-actions"><button class="icon-btn menu-toggle" style="display:none" data-action="open-menu">☰</button>${state.view==='myday'?'<button class="icon-btn" data-action="suggestions" title="建议">💡</button>':''}<button class="icon-btn" data-action="sort-menu" title="排序">↕</button><button class="icon-btn" data-action="more" title="更多">•••</button></div>${state.moreOpen?moreMenu():''}</div><div class="task-list">${cards||emptyState(info)}</div>${!['assigned','flagged'].includes(state.view)?`<form class="add-task" id="addTask"><span>＋</span><input name="title" autocomplete="off" placeholder="添加任务" aria-label="添加任务"></form>`:''}</div>`;
  m.querySelector('#addTask')?.addEventListener('submit',e=>{e.preventDefault();addTask(new FormData(e.target).get('title'));e.target.reset()})
}
function moreMenu(){return `<div class="more-menu"><button class="menu-row" data-action="sort-menu"><span>⇅</span><span>排序方式</span><b>›</b></button><div class="theme-label">主题</div><div class="theme-grid">${themes.map(([id,color])=>`<button class="theme-swatch ${state.theme===id?'chosen':''}" data-theme="${id}" style="background:${color}" aria-label="主题 ${id}"></button>`).join('')}</div><div class="menu-sep"></div><button class="menu-row" data-action="print"><span>▣</span><span>打印列表</span></button><button class="menu-row" data-action="jarvis"><span>✦</span><span>发送给 Jarvis</span></button><button class="menu-row" data-action="pin"><span>⌖</span><span>从开始菜单取消固定</span></button></div>`}
function emptyState(info){return `<div class="empty"><div><div class="empty-icon">${info.icon}</div><h2>${state.search?'没有匹配的任务':'这里很清爽'}</h2><p>${state.search?'试试其他关键词':'添加一项任务，开始规划吧'}</p></div></div>`}
function card(t){let meta=[];if(state.view!=='tasks')meta.push(listName(t.list));if(t.myDay&&state.view!=='myday')meta.push('☼ 我的一天');if(t.due)meta.push(`<span class="${t.due<todayISO()?'overdue':''}">▦ ${t.due===todayISO()?'今天':formatDate(t.due)}</span>`);if(t.repeat)meta.push('↻ '+t.repeat);if(t.steps.length)meta.push(`${t.steps.filter(s=>s.done).length}/${t.steps.length}`);return `<article class="task-card ${state.selected===t.id?'selected':''}" data-task="${t.id}"><button class="check ${t.completed?'done':''}" data-action="complete" data-id="${t.id}" aria-label="${t.completed?'恢复':'完成'}">✓</button><div><div class="task-title ${t.completed?'done':''}">${esc(t.title)}</div><div class="meta">${meta.length?meta.join('<span>·</span>'):esc(listName(t.list))}</div></div><button class="star ${t.important?'important':''}" data-action="star" data-id="${t.id}" aria-label="重要">${t.important?'★':'☆'}</button></article>`}
function listName(id){return id==='tasks'?'任务':state.lists.find(l=>l.id===id)?.name||'任务'}
function formatDate(iso){return new Intl.DateTimeFormat('zh-CN',{month:'short',day:'numeric'}).format(new Date(iso+'T12:00:00'))}
function addTask(title){title=String(title||'').trim();if(!title)return;const list=builtIns.some(x=>x[0]===state.view)?'tasks':state.view;state.tasks.unshift({id:crypto.randomUUID(),title,list,important:state.view==='important',myDay:state.view==='myday',completed:false,due:state.view==='planned'?todayISO():null,reminder:null,repeat:null,note:'',steps:[],created:Date.now()});render();toast('任务已添加')}
function renderDetail(){const p=document.querySelector('#detailPanel'),t=state.tasks.find(x=>x.id===state.selected);if(!t){p.className='detail-panel';p.innerHTML='';return}p.className='detail-panel open';p.innerHTML=`<div class="panel-header"><span>任务详情</span><button class="close-btn" data-action="close-detail">×</button></div><div class="detail-body"><div class="detail-card"><div class="detail-task"><div class="detail-title-row"><button class="check ${t.completed?'done':''}" data-action="complete" data-id="${t.id}">✓</button><input class="detail-title" data-field="title" value="${esc(t.title)}"><button class="star ${t.important?'important':''}" data-action="star" data-id="${t.id}">${t.important?'★':'☆'}</button></div></div><div class="step-list">${t.steps.map((s,i)=>`<div class="step"><input type="checkbox" data-step-done="${i}" ${s.done?'checked':''}><input type="text" data-step="${i}" value="${esc(s.title)}"><button class="delete-btn" data-remove-step="${i}">×</button></div>`).join('')}</div><div class="add-step">＋<input id="newStep" placeholder="添加步骤"></div></div><div class="detail-card"><button class="detail-action ${t.myDay?'active':''}" data-action="toggle-myday">☼　${t.myDay?'已添加到我的一天':'添加到我的一天'}</button></div><div class="detail-card"><button class="detail-action" data-action="reminder">⏰　${t.reminder?formatDateTime(t.reminder):'提醒我'}</button><button class="detail-action" data-action="due">▦　${t.due?'截止 '+formatDate(t.due):'添加截止日期'}</button><button class="detail-action" data-action="repeat">↻　${t.repeat||'重复'}</button></div><div class="detail-card"><button class="detail-action" data-action="file">♧　添加文件</button></div><div class="detail-card"><textarea class="note" data-field="note" placeholder="添加备注">${esc(t.note)}</textarea></div><div class="detail-footer"><span>创建于 ${formatDate(new Date(t.created).toISOString().slice(0,10))}</span><button class="delete-btn" data-action="delete" title="删除">⌫</button></div></div>`;
  p.querySelectorAll('[data-field]').forEach(el=>el.addEventListener('change',()=>{t[el.dataset.field]=el.value;render()}));p.querySelector('#newStep').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.value.trim()){t.steps.push({title:e.target.value.trim(),done:false});render()}});p.querySelectorAll('[data-step]').forEach(el=>el.addEventListener('change',()=>{t.steps[+el.dataset.step].title=el.value;save()}));p.querySelectorAll('[data-step-done]').forEach(el=>el.addEventListener('change',()=>{t.steps[+el.dataset.stepDone].done=el.checked;save()}));p.querySelectorAll('[data-remove-step]').forEach(el=>el.addEventListener('click',()=>{t.steps.splice(+el.dataset.removeStep,1);render()}))
}
function formatDateTime(v){return new Intl.DateTimeFormat('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v))}
function renderSuggestions(){const p=document.querySelector('#suggestionsPanel');if(!state.suggestions){p.className='suggestions-panel';p.innerHTML='';return}const candidates=state.tasks.filter(t=>!t.completed&&!t.myDay).slice(0,8);p.className='suggestions-panel open';p.innerHTML=`<div class="panel-header"><span>建议</span><button class="close-btn" data-action="close-suggestions">×</button></div><div class="suggest-group"><div class="suggest-label"><span>建议添加</span><span>•••</span></div>${candidates.map(t=>`<div class="suggest-card"><button class="check" data-action="complete" data-id="${t.id}">✓</button><div><div>${esc(t.title)}</div><div class="meta">${esc(listName(t.list))}</div></div><button class="plus" data-action="suggest-add" data-id="${t.id}">＋</button></div>`).join('')||'<div class="empty"><p>今天的计划已经很充实了</p></div>'}</div>`}
function modal(html){const d=document.createElement('div');d.className='modal-backdrop';d.innerHTML=`<div class="modal">${html}</div>`;document.body.append(d);d.addEventListener('click',e=>{if(e.target===d||e.target.matches('[data-modal-close]'))d.remove()});return d}
function newList(){const d=modal(`<h2>新建列表</h2><form id="listForm"><input name="name" autofocus placeholder="列表名称"><div class="modal-actions"><button type="button" class="btn" data-modal-close>取消</button><button class="btn primary">创建</button></div></form>`);d.querySelector('input').focus();d.querySelector('form').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name)return;const id='list-'+Date.now();state.lists.push({id,name});state.view=id;d.remove();render()}}
function dateModal(kind){const t=state.tasks.find(x=>x.id===state.selected);if(!t)return;const value=(kind==='due'?t.due:(t.reminder||'').slice(0,10))||todayISO();const d=modal(`<h2>${kind==='due'?'选择截止日期':'选择提醒时间'}</h2><input type="${kind==='due'?'date':'datetime-local'}" id="dateValue" value="${kind==='due'?value:value+'T09:00'}"><div class="modal-actions"><button class="btn" data-modal-close>取消</button><button class="btn primary" id="saveDate">保存</button></div>`);d.querySelector('#saveDate').onclick=()=>{const v=d.querySelector('#dateValue').value;if(kind==='due')t.due=v;else t.reminder=v;d.remove();render()}}
function repeatModal(){const t=state.tasks.find(x=>x.id===state.selected),d=modal(`<h2>重复</h2><select id="repeat"><option value="">不重复</option><option>每天</option><option>每周</option><option>每月</option><option>每年</option></select><div class="modal-actions"><button class="btn" data-modal-close>取消</button><button class="btn primary" id="saveRepeat">保存</button></div>`);d.querySelector('#repeat').value=t.repeat||'';d.querySelector('#saveRepeat').onclick=()=>{t.repeat=d.querySelector('#repeat').value;d.remove();render()}}
document.addEventListener('click',e=>{const theme=e.target.closest('[data-theme]');if(theme){state.theme=theme.dataset.theme;state.moreOpen=false;render();return}const v=e.target.closest('[data-view]');if(v){state.view=v.dataset.view;state.selected=null;state.search='';state.sidebarOpen=false;state.moreOpen=false;render();return}const task=e.target.closest('[data-task]');const a=e.target.closest('[data-action]');if(task&&!a){state.selected=task.dataset.task;state.suggestions=false;render();return}if(!a){if(state.moreOpen&&!e.target.closest('.more-menu')){state.moreOpen=false;render()}return}const id=a.dataset.id,t=state.tasks.find(x=>x.id===id),selected=state.tasks.find(x=>x.id===state.selected);switch(a.dataset.action){case'complete':t.completed=!t.completed;render();toast(t.completed?'任务已完成':'任务已恢复');break;case'star':t.important=!t.important;render();break;case'new-list':newList();break;case'close-detail':state.selected=null;render();break;case'suggestions':state.suggestions=!state.suggestions;state.selected=null;render();break;case'close-suggestions':state.suggestions=false;render();break;case'suggest-add':t.myDay=true;render();toast('已添加到我的一天');break;case'toggle-completed':state.completedOpen=!state.completedOpen;render();break;case'toggle-myday':selected.myDay=!selected.myDay;render();break;case'due':dateModal('due');break;case'reminder':dateModal('reminder');break;case'repeat':repeatModal();break;case'delete':state.tasks=state.tasks.filter(x=>x.id!==selected.id);state.selected=null;render();toast('任务已删除');break;case'file':toast('演示版不上传文件，可在备注中记录链接');break;case'more':state.moreOpen=!state.moreOpen;render();break;case'sort-menu':state.sortMode=state.sortMode==='created'?'important':state.sortMode==='important'?'alpha':'created';state.moreOpen=false;render();toast('排序：'+({created:'创建时间',important:'重要性',alpha:'字母顺序'}[state.sortMode]));break;case'print':window.print();break;case'jarvis':state.moreOpen=false;render();toast(`已将“${viewInfo().name}”发送给 Jarvis`);break;case'pin':state.moreOpen=false;render();toast('已从开始菜单取消固定');break;case'open-menu':state.sidebarOpen=true;render();break;case'home':state.view='myday';render();break}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.selected||state.suggestions||state.sidebarOpen){state.selected=null;state.suggestions=false;state.sidebarOpen=false;render()}}});
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),1800)}
render();
